Definition range_pages (lo len : Z) : list word :=
  pages_from (lo / 4096 * 4096) (Z.to_nat ((lo + len - 1) / 4096 - lo / 4096 + 1)).

Lemma range_pages_length : forall lo len, 0 <= lo -> 0 < len ->
  Z.of_nat (length (range_pages lo len)) <= len / 4096 + 2.
